BEGIN TRANSACTION;
CREATE TABLE "diccionario" ("id","categoría","código_indicador","nombre_visible","tipo","fórmula_regla_de_cálculo","unidad","responsable_carga","fuente_sugerida","frecuencia","desglose_segmento_detalle","origen","comentario","periodicidad");
CREATE TABLE "gastos_homologados" ("periodo","pais","entidad","moneda","codigo_comun","categoria","rubro_comun","subrubro","tercero_detalle","saldo_inicial","debitos","creditos","saldo_final_fuente","saldo_presentacion_ytd","movimiento_mes","fuente_archivo","referencia","confianza","revisar","fundamento");
CREATE TABLE "gastos_mapeo" ("codigo_comun","rubro_comun","categoria_comun","indicador_dashboard","detalle_dashboard","area_dashboard","usar_en_grafica","criterio","estado_mapeo");
CREATE TABLE "gastos_puente" ("periodo","pais","entidad","moneda","codigo_comun","rubro_comun","indicador_dashboard","detalle_dashboard","area_dashboard","valor_mes","valor_ytd","fuente","calidad_mapeo","nota");
CREATE TABLE "gastos_resumen" ("periodo","pais","entidad","moneda","indicador_dashboard","detalle_dashboard","area_dashboard","valor_mes","valor_ytd","filas_fuente","nota");
CREATE TABLE "indicadores" ("periodo","pais","compania","moneda","escenario","codigo_indicador","segmento","detalle","valor","unidad","comentario","area","area_responsable","periodicidad");
CREATE TABLE "trm" ("periodo","trm_cop_usd","fuente","trm_promedio_mercado");
CREATE TABLE "trm_peru" ("periodo","par","tc_pen_usd","factor_usd_pen","fuente");
CREATE VIEW v_consol_suma AS
      SELECT periodo, codigo_indicador, segmento, ROUND(SUM(valor),2) AS suma_paises
      FROM indicadores
      WHERE pais IN ('EE.UU.','Perú','Costa Rica','Colombia') AND escenario='Real'
      GROUP BY periodo, codigo_indicador, segmento;
CREATE VIEW v_consol_guardado AS
      SELECT periodo, codigo_indicador, segmento, ROUND(SUM(valor),2) AS guardado
      FROM indicadores WHERE pais='Consolidado' AND escenario='Real'
      GROUP BY periodo, codigo_indicador, segmento;
COMMIT;
